public String toPostfix(String s) {
    StringBuilder out = new StringBuilder();
    Deque<Character> ops = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (isOperand(c)) {
            out.append(c);
        } else if (c == '(') {
            ops.push(c);
        } else if (c == ')') {
            while (ops.peek() != '(') {
                out.append(ops.pop());
            }
            ops.pop();
        } else {
            while (!ops.isEmpty() && ops.peek() != '('
                    && binds(ops.peek(), c)) {
                out.append(ops.pop());
            }
            ops.push(c);
        }
    }
    while (!ops.isEmpty()) {
        out.append(ops.pop());
    }
    return out.toString();
}
